h1 {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  padding: 24px;
  text-align: center;
  font-size: 1.5rem;
  font-weight: 600;
  margin: 0;
}

.message-list {
  height: 500px;
  overflow-y: auto;
