  border-top: 1px solid #e9ecef;
}

.message-form input {
  width: 100%;
  padding: 12px 16px;
  border: 2px solid #e9ecef;
  border-radius: 8px;
  font-size: 1rem;
  transition: border-color 0.2s;
  margin-bottom: 12px;
}

.message-form input:focus {
  outline: none;
  border-color: #667eea;
}

.message-form button {
  width: 100%;
  padding: 12px 16px;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  border: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: opacity 0.2s, transform 0.1s;
}

.message-form button:hover {
  opacity: 0.9;
}

.message-form button:active {
  transform: scale(0.98);
}

.message-form button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.status {
  padding: 12px 20px;
  text-align: center;
  font-size: 0.875rem;
  font-weight: 500;
}

.status.connected {
  color: #28a745;
  background: #d4edda;
}

.status.disconnected {
  color: #6c757d;
  background: #e2e3e5;
}

.status.error {
  color: #dc3545;
  background: #f8d7da;
}

/* Scrollbar styling */
.message-list::-webkit-scrollbar {
  width: 8px;
}

