  font-size: 0.875rem;
  font-weight: 500;
}

.status.connected {
  color: #28a745;
  background: #d4edda;
}

.status.disconnected {
  color: #6c757d;
  background: #e2e3e5;
}

.status.error {
  color: #dc3545;
  background: #f8d7da;
}

